class MgmdSnoopingGroupTypeDefinition(TextualConvention, Integer32):
    description = 'This type distinguishes the different ways of\r\n                     tracking groups on this device having\r\n                     multicast joins. The method of tracking is primarily\r\n                     determined by the MGMD Snooping feature configuration.\r\n                     In particular if the snooping feature is enabled then\r\n                     port level tracking is the default, which results in\r\n                     Filtered groups. When users create static groups\r\n                     these groups will be categorized as static and\r\n                     groups will exist till user unconfigure them.'
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2))
    namedValues = NamedValues(("filtered", 1), ("static", 2))

class MgmdSnoopingConfigPortModeType(TextualConvention, Integer32):
    description = 'Mode in auto means MGMD Snooping will be working\r\n              as per specs on these ports that is when a join comes for\r\n              a group on this port data packets sent to that group\r\n              will be forwarded on that port. Blocked means all\r\n              outgoing data packets and incoming joins will be blocked\r\n              on that port.Forward means all the packets irrespective\r\n              of whether the join is received for a group or not\r\n              packets will be sent or received on these ports in\r\n              other wording forwarded ports acts like router detected\r\n              ports.'
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2, 3))
    namedValues = NamedValues(("auto", 1), ("blocked", 2), ("forward", 3))

